window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-40301\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλαῖεν</h1><div class=\"entry-meta\"><span>DGP · ordem 843 na letra τ · nº geral 40301</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a pl. opt. aor.2 poét. de τλάω.</p></section></article>\n<article id=\"entry-dgp-40302\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλάμων</h1><div class=\"entry-meta\"><span>DGP · ordem 844 na letra τ · nº geral 40302</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = τλήμων.</p></section></article>\n<article id=\"entry-dgp-40303\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλατός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 845 na letra τ · nº geral 40303</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = τλητός.</p></section></article>\n<article id=\"entry-dgp-40304\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλάω</h1><div class=\"entry-meta\"><span>DGP · ordem 846 na letra τ · nº geral 40304</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(pres. desus., fut. τλήσομαι e τλήσω, aor.1 ép. ἐτάλασσα, aor.2 ἔτλην dór. ἔτλαν, imper. τλῆθι, subj. τλῶ, opt. τλαίην, inf. τλῆναι, part. τλάς, ᾶσα, άν, perf. com sent. de pres. τέτληκα) poét. 1 suportar; sofrer algo, ac. ou inf. ou part.: πολλὰ γὰρ ἔτλην hom. suportei muitos sofrimentos, τλῆτε, φίλοι hom. suportai bem, amigos, τέτλαθι, μῆτερ ἐμή, καὶ ἀνάσχεο hom. suporta, minha mãe, e resigna-te, τετληότι θυμῷ hom. com alma paciente, com coração paciente, οὐ γὰρ ἂν τλαίην ἰδεῖν Ar. pois eu não suportaria ver, τάδε καὶ τέτλαμεν εἰσορόωντες hom. também disso suportamos ser testemunhas, suportamos ainda isso com paciência 2 ser forte em rel. a algo, ac.; fortalecer: τλάσας τὸ γενναῖον φρενί sóf. fortalecendo a nobreza no coração 3 com neg., não fazer o esforço de; não julgar necessário, dat. 4 ter coragem de; ousar, inf.: ἔτλα οὐράνιον φῶς ἀλλάξαι sóf. [Dânae] suportou ser privada da luz do céu; πῶς ἔτλης σὰς ὄψεις μαρᾶναι; sóf. como tiveste coragem de mutilar os olhos?</p></section></article>\n<article id=\"entry-dgp-40305\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλῆθι</h1><div class=\"entry-meta\"><span>DGP · ordem 847 na letra τ · nº geral 40305</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. τλάω.</p></section></article>\n<article id=\"entry-dgp-40306\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλῆμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 848 na letra τ · nº geral 40306</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1a pl. aor.2 poét. de τλάω.</p></section></article>\n<article id=\"entry-dgp-40307\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλημόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 849 na letra τ · nº geral 40307</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 miseravelmente 2 com coragem; com paciência; com resignação. 〈τλήμων〉</p></section></article>\n<article id=\"entry-dgp-40308\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλημοσύνη, ης ( ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 850 na letra τ · nº geral 40308</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 adversidade; desgraça; vida miserável 2 paciência na adversidade; coragem; resignação. 〈τλήμων〉</p></section></article>\n<article id=\"entry-dgp-40309\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλήμων,</h1><div class=\"entry-meta\"><span>DGP · ordem 851 na letra τ · nº geral 40309</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. τλάμων, ων, ον gen. ονος voc. τλῆμον 1 que suporta pacientemente ou com coragem algo ou alguém, ac. ou gen.; paciente; corajoso 2 miserável; infeliz 3 que se encarrega de; que assume; empreendedor; corajoso 4 insolente; arrogante. 〈τλάω〉</p></section></article>\n<article id=\"entry-dgp-40310\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 852 na letra τ · nº geral 40310</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. τλάω.</p></section></article>\n<article id=\"entry-dgp-40311\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλησικάρδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 853 na letra τ · nº geral 40311</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de coração paciente; corajoso 2 de coração duro; impiedoso. 〈τλάω, καρδία〉</p></section></article>\n<article id=\"entry-dgp-40312\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλῆτε</h1><div class=\"entry-meta\"><span>DGP · ordem 854 na letra τ · nº geral 40312</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a pl. imper. aor.2 de τλάω.</p></section></article>\n<article id=\"entry-dgp-40313\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 855 na letra τ · nº geral 40313</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 paciente; corajoso 2 tolerável. 〈τλάω〉</p></section></article>\n<article id=\"entry-dgp-40314\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τλήτω</h1><div class=\"entry-meta\"><span>DGP · ordem 856 na letra τ · nº geral 40314</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. imper. aor.2 de τλάω.</p></section></article>\n<article id=\"entry-dgp-40315\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τμάγεν</h1><div class=\"entry-meta\"><span>DGP · ordem 857 na letra τ · nº geral 40315</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a pl. poét. aor.2 pas. de τμήγω.</p></section></article>\n<article id=\"entry-dgp-40316\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τμήγω</h1><div class=\"entry-meta\"><span>DGP · ordem 858 na letra τ · nº geral 40316</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. τμήξω, aor.1 ἔτμηξα dór. ἔτμᾱξα, aor.2 ἔτμαγον, perf. desus.; méd. aor. ἐτμηξάμην; pas. aor.2 ἐτμάγην e ἐτμήγην) 1 cortar; partir; fender ♦ méd. pas. 2 separar-se; dividir-se.</p></section></article>\n<article id=\"entry-dgp-40317\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τμήδην</h1><div class=\"entry-meta\"><span>DGP · ordem 859 na letra τ · nº geral 40317</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com corte; fazendo um corte. 〈τέμνω, -δην〉</p></section></article>\n<article id=\"entry-dgp-40318\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τμηθῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 860 na letra τ · nº geral 40318</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. pas. de τέμνω.</p></section></article>\n<article id=\"entry-dgp-40319\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τμῆσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 861 na letra τ · nº geral 40319</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de devastar; devastação: τ. γῆς Ἑλληνικῆς plat. devastação do território grego 2 ação de secionar; corte; seção 3 divisão lógica 4 Gram. tmese. 〈τέμνω〉</p></section></article>\n<article id=\"entry-dgp-40320\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τμητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 862 na letra τ · nº geral 40320</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de τέμνω.</p></section></article>\n<article id=\"entry-dgp-40321\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τμητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 863 na letra τ · nº geral 40321</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cortante 2 penetrante; pungente 3 Ret. conciso; incisivo; preciso. 〈τμητός〉</p></section></article>\n<article id=\"entry-dgp-40322\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τμητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 864 na letra τ · nº geral 40322</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cortado; talhado; rasgado 2 que se pode cortar ou separar; divisível. 〈τέμνω〉</p></section></article>\n<article id=\"entry-dgp-40323\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τό</h1><div class=\"entry-meta\"><span>DGP · ordem 865 na letra τ · nº geral 40323</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 art. def. n.; cf. ὁ 2 poét. = ὅ, pron. rel. n.; cf. ὅς 3 pron. dem. n. = τοῦτο.</p></section></article>\n<article id=\"entry-dgp-40324\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόγε</h1><div class=\"entry-meta\"><span>DGP · ordem 866 na letra τ · nº geral 40324</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">n. de ὅγε.</p></section></article>\n<article id=\"entry-dgp-40325\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόδε</h1><div class=\"entry-meta\"><span>DGP · ordem 867 na letra τ · nº geral 40325</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">n. de ὅδε.</p></section></article>\n<article id=\"entry-dgp-40326\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοδί</h1><div class=\"entry-meta\"><span>DGP · ordem 868 na letra τ · nº geral 40326</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">τόδε.</p></section></article>\n<article id=\"entry-dgp-40327\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 869 na letra τ · nº geral 40327</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. dem. correl. de πόθεν, ποθέν e ὅθεν 1 daí; a partir disso; por conseguinte 2 adv. rel. de onde.</p></section></article>\n<article id=\"entry-dgp-40328\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόθι</h1><div class=\"entry-meta\"><span>DGP · ordem 870 na letra τ · nº geral 40328</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. dem. correl. de πόθι, ποθί e ὅθι 1 aí mesmo 2 adv. rel. onde.</p></section></article>\n<article id=\"entry-dgp-40329\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοι1</h1><div class=\"entry-meta\"><span>DGP · ordem 871 na letra τ · nº geral 40329</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">partíc. afirm. encl. 1 com certeza; seguramente, como reforço de afirm. de caráter geral αἰσχρόν τοι δηρόν τε μένειν κενεόν τε νέεσθαι hom. com certeza ele se envergonha de ficar tanto tempo e retornar de mãos vazias 2 com certeza; sem dúvida; pode ter a certeza, em disc. dir.: εἰ κτενοῦμεν ἄλλον ἀντ᾽ ἄλλου, σύ τοι πρώτη θάνοις ἄν sóf. se fazemos perecer um pelo outro, sem dúvida tu poderias morrer em primeiro lugar, ἴσθι τοι τείσουσά γ᾽ ἀξίαν δίκην sóf. sabe bem que, sem dúvida, serás punido como mereces 3 então, em inter.: ποῦ τοι ἀπειλαὶ οἴχονται; hom. então, que é que se tornaram as ameaças? 4 veja bem, então, para resumir o que foi dito: ταύτης τοι γενεῆς τε καὶ αἵματος εὔχομαι εἶναι hom. veja bem então de que estirpe e de que sangue me vanglorio de ser 5 sim; com certeza, em resp. afirm. ou neg.: ἦ γάρ τοι hom. sim, com certeza, οὐ γάρ τοι hom. não, com certeza 6 certamente, em or. subord.cond., final, causal ou adj.: ἐὰν δέ τοι sóf. se é verdade que, ὅπως τὸ συγγενές τοι κἀπ᾽ ἐμοῦ θρήνων τύχῃ sóf. para que aquele que é da mesma estirpe que eu receba com certeza as lamentações, ἐπεί τοι sóf. já que sem dúvida, ὅτι τοι ar. porque certamente, οὗ τοι ἕνεκα ἠρόμην plat. pela qual razão, precisamente 7 certamente; entretanto, com partíc. adversativas: ἀλλά τοι e ἀλλὰ... τοι mas entretanto, mas sem dúvida 8 certamente; com certeza, com outras partíc.: γάρ τοι pois, com certeza, γέ τοι com certeza.</p></section></article>\n<article id=\"entry-dgp-40330\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοι2</h1><div class=\"entry-meta\"><span>DGP · ordem 872 na letra τ · nº geral 40330</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. sing. encl. dór., eól., jôn. e ép. de σύ</p></section></article>\n<article id=\"entry-dgp-40331\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοί3, ταί</h1><div class=\"entry-meta\"><span>DGP · ordem 873 na letra τ · nº geral 40331</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. masc. e fem. pl. ép. e jôn. do art. def. ὅ, ἥ ou do rel. ὅς, ἥ.</p></section></article>\n<article id=\"entry-dgp-40332\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιαδί</h1><div class=\"entry-meta\"><span>DGP · ordem 874 na letra τ · nº geral 40332</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. n. át. de τοιόσδε.</p></section></article>\n<article id=\"entry-dgp-40333\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιγάρ</h1><div class=\"entry-meta\"><span>DGP · ordem 875 na letra τ · nº geral 40333</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">partíc. inferencial usada em início de frase, é por isso, também; eh! bem, então; portanto; consequentemente, pois então.</p></section></article>\n<article id=\"entry-dgp-40334\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιγαροῦν,</h1><div class=\"entry-meta\"><span>DGP · ordem 876 na letra τ · nº geral 40334</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. τοιγαρῶν partíc. usada no início de frase 1 eis então porque; por essa razão, portanto 2 por exemplo. 〈τοιγάρ, οὖν〉</p></section></article>\n<article id=\"entry-dgp-40335\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιγάρτοι</h1><div class=\"entry-meta\"><span>DGP · ordem 877 na letra τ · nº geral 40335</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">forma enfát. de τοιγάρ usada no início de frase.</p></section></article>\n<article id=\"entry-dgp-40336\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιγαρῶν</h1><div class=\"entry-meta\"><span>DGP · ordem 878 na letra τ · nº geral 40336</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn.= τοιγαροῦν.</p></section></article>\n<article id=\"entry-dgp-40337\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοῖιν</h1><div class=\"entry-meta\"><span>DGP · ordem 879 na letra τ · nº geral 40337</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. dual masc. ou gen. n. ou dat. dual do art. def. ὁ, ἡ, τό.</p></section></article>\n<article id=\"entry-dgp-40338\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 880 na letra τ · nº geral 40338</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dual fem. ou masc., gen. ou dat. do art. def. ὁ, ἡ, τό.</p></section></article>\n<article id=\"entry-dgp-40339\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοίνυν</h1><div class=\"entry-meta\"><span>DGP · ordem 881 na letra τ · nº geral 40339</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">partíc. át. 1 introduzindo uma conclusão, portanto; assim; então; com efeito: ἔλεγες τοίνυν δὴ ὅτι plat. dizias então justamente que 2 em diálogo, introduzindo uma resposta, começando ou continuando um argumento, ou passando a novo tópico, bem; então: ἐγὼ μὲν τοίνυν xen. bem, então; quanto a mim. 〈τοι, νύν〉</p></section></article>\n<article id=\"entry-dgp-40340\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοῖο</h1><div class=\"entry-meta\"><span>DGP · ordem 882 na letra τ · nº geral 40340</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. masc. sing. ép. e jôn. do art. def. ὁ.</p></section></article>\n<article id=\"entry-dgp-40341\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοῖος, τοία</h1><div class=\"entry-meta\"><span>DGP · ordem 883 na letra τ · nº geral 40341</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, jôn., τοίη, τοῖον pron. dem. 1 tal; de tal sorte, em rel. a algo, ac., dat. ou inf.: τοῖα ἔλεξε pínd. disse tais coisas, i.e., disse o seguinte, τοῖος ἢ τοῖος, τοῖος καὶ τοῖος plat. tal ou tal, τοῖος δέ τε χεῖρας hom. tal, quanto às mãos, τεύχεσι τοῖος hom. tal, pelas armas, τοῖος ἰδεῖν teóg. tal, de ver, i.e., de tal aspecto 2 em correl. com inter. ποῖος ou com rel. οἷος, ὁποῖος, ὅς, ou com adv. rel. ὅπως: τοῖος ἐὼν οἷος οὔτις Ἀχαιῶν hom. sendo tal que nenhum dos gregos; οἵηπερ φύλλων γενεή, τοιὴ δὲ καὶ ἀνδρῶν hom. tal é a geração das folhas, tal também a dos homens, ἥ τέ με τοῖον ἔθηκεν, ὅπως ἐθέλει hom. [Atena] me põe tal como ela deseja 3 apto; capaz de, inf.: τοῖοι ἀμυνέμεν hom. capazes de resistir 4 com adj., tão; tanto: πέλαγος μέγα τοῖον hom. mar tão vasto, i.e., muito vasto, τοῖος μέγας δοῦπος hes. fragor tão intenso, τοῖος μέγιστος δοῦπος hes. fragor desmesuradamente intenso, ἀβληχρὸς μάλα τοῖος hom. [morte] tão doce demais ♦ τοῖον adv. 5 de tal modo, i.e., desse modo ou nesse ponto: τοῖον ὑποτρομέουσιν hom. a tal ponto eles são trêmulos, θάμα τοῖον hom. de tal modo frequente, tão frequente, muito frequente.</p></section></article>\n<article id=\"entry-dgp-40342\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιόσδε, άδε</h1><div class=\"entry-meta\"><span>DGP · ordem 884 na letra τ · nº geral 40342</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, jôn., ήδε, όνδε pron. dem. 1 em sent. eufór. ou disfór., tal que eis; tal em rel. a, ac. : ἀλλ’ ὅδ’ ἐγὼ τοιόσδε hom. sou bem eu que tu vês, τοιάσδε ποινὰς τίνω ésql. tal é o castigo que eu sofro, οὔ κε κακοὶ τοιοῦσδε τέκοιεν hom. malvados não teriam gerado tais homens, τοιόσδε τοσόσδε τε λαός hom. um povo tal e tão numeroso, ἐν τῷ τοιῷδε her. em tal situação, i.e., em uma situação tão crítica ou tão triste, τοιόσδε ἠμὲν δέμας ἠδὲ καὶ ἔργα hom. tal para o corpo e para a ação; às vezes com art., ἐν τῇ τοιᾴδε ἀνάγκῃ tuc. em uma necessidade tão opressora, οἱ τοιοίδε sóf. os homens tais; em correl. com rel., ἀοιδοῦ τοιοῦδ᾽ οἷος ὅδ’ ἐστι hom. um aedo tal como é este 2 com τίς para afirmar de maneira menos precisa, mais ou menos: τοιόσδε τις tuc. mais ou menos este 3 capaz de, inf.: τοιόσδε ἀμύνειν hom. a ponto de resistir, capaz de resistir 4 em uma narrativa, tal como este, em rel. com o que segue: τοιάδε her. coisas tais como as seguintes, κατὰ τοιόνδε [τρόπον] her. da maneira seguinte. 〈τοῖος, -δε〉</p></section></article>\n<article id=\"entry-dgp-40343\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιοσδί, αδί, ονδί</h1><div class=\"entry-meta\"><span>DGP · ordem 885 na letra τ · nº geral 40343</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = τοιόσδε.</p></section></article>\n<article id=\"entry-dgp-40344\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιοῦτος, τοιαύτη, τοιοῦτο</h1><div class=\"entry-meta\"><span>DGP · ordem 886 na letra τ · nº geral 40344</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e τοιοῦτον gen. pl. masc. fem. n. τοιούτων pron. dem. 1 com sent. eufór. ou disfór., tal; de tal tipo, em rel. com o que precede: κἀγὼ τοιοῦτός εἰμι ésql. eu também sou desta opinião, τοιοῦτος ὤν xen. com tais sentimentos, com tais qualidades, ταῦτα καὶ τοιαῦτα πολλά xen. estas coisas e muitas outras semelhantes, ἐμπίπτειν εἰς τοιοῦτον plat. cair em tal situação (tão humilhante), τοιοῦτον Ἀχαιῶν hom. um tal homem entre os aqueus, ἐν τοιούτῳ τῆς οἰκίας xen. em tal lugar da casa; com art., ὁ τοιοῦτος át. aquele que está feito assim, que tem tais sentimentos, οἱ τοιοῦτοι ésql. tais pessoas, τὸ τοιοῦτον tuc. uma tal conduta, ἐν τῷ τοιούτῳ ou ἐν τοῖς τοιούτοις em tal lugar ou em tais circunstâncias, διὰ τὸ τοιοῦτον tuc. por tal motivo; em correl. com οἷος, ὅς: οὔπω τοιοῦτον ἐγὼν ἴδον ὀφθαλμοῖσιν, οἷον Ὀδυσσῆος hom. ainda não tinha visto com meus olhos alguém igual a Odisseu, λόγοις τοιούτοις, οἷς σὺ μὴ τέρψει sóf. palavras tais com que não te comprazerás; com ὥστε e inf., οὐ γὰρ τοιοῦτος ὥστε ésql. pois ele não é homem para; em respostas, τοιαῦτα eur. é isso 2 com τις para indicação menos precisa, mais ou menos: ἡ διάρριψις τοιαύτη τις ἐγένετο xen. eis aproximadamente como se deu a esparramação [das tralhas], τοιοῦτόν τι ἔπος pínd. tal palavra, aproximadamente ♦ τοιοῦτον adv. 3 de tal modo: τ. εἶναι xen. comportar-se assim, agir desse modo 4 pl. τοιαῦτα de certo modo. 〈τοῖος, οὗτος〉</p></section></article>\n<article id=\"entry-dgp-40345\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιουτοσί, τοιαυτηΐ, τοιουτοΐ</h1><div class=\"entry-meta\"><span>DGP · ordem 887 na letra τ · nº geral 40345</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e τοιουτονί át. = τοιοῦτος.</p></section></article>\n<article id=\"entry-dgp-40346\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιουτότροπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 888 na letra τ · nº geral 40346</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de tal modo; de mesmo modo. 〈τοιοῦτος, τρόπος〉</p></section></article>\n<article id=\"entry-dgp-40347\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιουτώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 889 na letra τ · nº geral 40347</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de tal maneira; de mesma maneira. 〈τοιοῦτος, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-40348\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοίσδεσι</h1><div class=\"entry-meta\"><span>DGP · ordem 890 na letra τ · nº geral 40348</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. poét. de ὅδε.</p></section></article>\n<article id=\"entry-dgp-40349\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοίχαρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 891 na letra τ · nº geral 40349</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chefe dos remadores. 〈τοῖχος, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-40350\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιχίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 892 na letra τ · nº geral 40350</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de τοῖχος.</p></section></article>\n<article id=\"entry-dgp-40351\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιχόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 893 na letra τ · nº geral 40351</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">projetar uma muralha; idealizar um muro. 〈τοῖχος〉</p></section></article>\n<article id=\"entry-dgp-40352\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοῖχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 894 na letra τ · nº geral 40352</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parede de casa, de templo 2 lateral; flanco de navio 3 lado de tenda 4 lateral; borda (de recipiente).</p></section></article>\n<article id=\"entry-dgp-40353\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιχωρυχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 895 na letra τ · nº geral 40353</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 perfurar; arrombar (muro, parede) para roubar 2 roubar. 〈τοιχωρύχος〉</p></section></article>\n<article id=\"entry-dgp-40354\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιχωρυχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 896 na letra τ · nº geral 40354</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de arrombar muro ou parede para praticar roubo; roubo. 〈τοιχωρύχος〉</p></section></article>\n<article id=\"entry-dgp-40355\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιχωρύχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 897 na letra τ · nº geral 40355</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ladrão. 〈τοῖχος, ὀρύσσω〉</p></section></article>\n<article id=\"entry-dgp-40356\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοκάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 898 na letra τ · nº geral 40356</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 que gerou ou gera; que pariu; que deu cria (animal) 2 prolífico; fértil (mulher) 3 que acabou de dar cria ♦ ἡ τοκάς 4 mãe.</p></section></article>\n<article id=\"entry-dgp-40357\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοκεύς, έως (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 899 na letra τ · nº geral 40357</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quem gera; pai ou mãe 2 fem. mãe 3 pl. e dual, pais; genitores. 〈τίκτω〉</p></section></article>\n<article id=\"entry-dgp-40358\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοκίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 900 na letra τ · nº geral 40358</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">emprestar dinheiro, ac., a juros. 〈τόκος〉</p></section></article>\n<article id=\"entry-dgp-40359\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοκισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 901 na letra τ · nº geral 40359</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">empréstimo a juros; usura. 〈τοκίζω〉</p></section></article>\n<article id=\"entry-dgp-40360\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοκιστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 902 na letra τ · nº geral 40360</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">agiota. 〈τοκίζω〉</p></section></article>\n<article id=\"entry-dgp-40361\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοκογλυφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 903 na letra τ · nº geral 40361</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">emprestar a juros exorbitantes; ser usurário; praticar usura. 〈τοκογλύφος〉</p></section></article>\n<article id=\"entry-dgp-40362\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοκογλύφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 904 na letra τ · nº geral 40362</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">credor voraz; usurário. 〈τόκος, γλύφω〉</p></section></article>\n<article id=\"entry-dgp-40363\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 905 na letra τ · nº geral 40363</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de dar à luz, de parir; nascimento; parto, ref. a mulheres: ἀπὸ τόκου xen. desde o nascimento 2 época do nascimento 3 período de gestação 4 tempo de parto 5 cria; ninhada 6 filho; criança 7 prole 8 raça; posteridade 9 produto ou fruto colhido na lavoura 10 produto do dinheiro emprestado; juros; rendimento.</p></section></article>\n<article id=\"entry-dgp-40364\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόλμα1, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 906 na letra τ · nº geral 40364</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 coragem; determinação para algo, gen. 2 ousadia; audácia; temeridade 3 impudência; atrevimento 4 ato audacioso, ousado demais.</p></section></article>\n<article id=\"entry-dgp-40365\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόλμα2</h1><div class=\"entry-meta\"><span>DGP · ordem 907 na letra τ · nº geral 40365</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">imper. pres. de τολμάω.</p></section></article>\n<article id=\"entry-dgp-40366\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 908 na letra τ · nº geral 40366</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. τολμήσω, aor. ἐτόλμησα, perf. τετόλ­μηκα) 1 ousar; atrever-se; ter determinação, coragem: τολμῶντες ἄνδρες tuc. homens corajosos, τόλμα κακοῖσιν teog. sê forte nas desgraças, τόλμα ou τόλμησον sóf. coragem! 2 resistir a; suportar corajosamente algo, ac. 3 resignar-se a, part.: ἐτόλμα βαλλόμενος hom. resignava-se a ser golpeado, submetia-se ser golpeado 4 ter coragem de; ter a audácia de, inf.: τόλμησον ὀρθῶς φρονεῖν ésql. ousa pensar corretamente 5 arriscar-se a; aventurar-se a; ter determinação para empreender algo, ac.: πόλεμον τολμήσαντα hom. tendo ousado empreender um combate ♦ pas. 6 suportar, tolerar a ousadia de alguém, ὑπό e gen: τολμῶν ὑπ᾽ ἐχθρῶν οἷ᾽ ἐτολμήθη πατήρ eur. tendo a mesma ousadia que meu pai suportou dos inimigos.</p></section></article>\n<article id=\"entry-dgp-40367\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμέω</h1><div class=\"entry-meta\"><span>DGP · ordem 909 na letra τ · nº geral 40367</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = τολμάω.</p></section></article>\n<article id=\"entry-dgp-40368\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόλμη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 910 na letra τ · nº geral 40368</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = τόλμα1.</p></section></article>\n<article id=\"entry-dgp-40369\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 911 na letra τ · nº geral 40369</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(superl. contr. τολμήστατος) 1 corajoso; paciente 2 determinado; audacioso; empreendedor 3 audaz; ousado; temerário. 〈τόλμα〉</p></section></article>\n<article id=\"entry-dgp-40370\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόλμημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 912 na letra τ · nº geral 40370</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação corajosa, determinada 2 traço de coragem ou de audácia 3 aventura; empreendimento temerário; temeridade. 〈τολμάω〉</p></section></article>\n<article id=\"entry-dgp-40371\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμηρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 913 na letra τ · nº geral 40371</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 corajoso; determinado; audacioso ♦ τὸ τολμηρόν 2 determinação; ousadia. 〈τόλμα〉</p></section></article>\n<article id=\"entry-dgp-40372\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμηρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 914 na letra τ · nº geral 40372</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. (comp. τολμηροτέρως e τολμηρότερον) com determinação; com audácia.</p></section></article>\n<article id=\"entry-dgp-40373\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμήστατος</h1><div class=\"entry-meta\"><span>DGP · ordem 915 na letra τ · nº geral 40373</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. τολμήεις.</p></section></article>\n<article id=\"entry-dgp-40374\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμητέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 916 na letra τ · nº geral 40374</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de τολμάω.</p></section></article>\n<article id=\"entry-dgp-40375\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 917 na letra τ · nº geral 40375</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">homem audacioso, empreendedor. 〈τολμάω〉</p></section></article>\n<article id=\"entry-dgp-40376\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμητός, ή</h1><div class=\"entry-meta\"><span>DGP · ordem 918 na letra τ · nº geral 40376</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, poét., ός, όν que se pode ou se deve ousar. 〈τολμάω〉</p></section></article>\n<article id=\"entry-dgp-40377\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολυπεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 919 na letra τ · nº geral 40377</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enrolar lã em novelo, em fuso 2 realizar pacientemente, penosamente; conduzir longamente: πόλεμον τολύπευσε hom. fez uma guerra arrastada, δόλους τολυπεύω hom. vou enovelando os fios de um dolo 3 resistir; aguentar (dor, sofrimento). 〈τολύπη〉</p></section></article>\n<article id=\"entry-dgp-40378\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολύπη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 920 na letra τ · nº geral 40378</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 novelo de lã enrolado em torno do fuso; novelo 2 lã pronta para ser fiada 3 novelo de qualquer coisa; bola 4 bolo esférico 5 tipo de abóbora.</p></section></article>\n<article id=\"entry-dgp-40379\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τομαῖος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 921 na letra τ · nº geral 40379</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, poét., ος, ον 1 cortado (cabelo) 2 cortado em pedaços; picado (remédio): ἄκος τομαῖον πημάτων ésql. remédio preparado contra dores. 〈τομή〉</p></section></article>\n<article id=\"entry-dgp-40380\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τομάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 922 na letra τ · nº geral 40380</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. pres. n. contr. τομῶν) ter necessidade de incisão. 〈τομή〉</p></section></article>\n<article id=\"entry-dgp-40381\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τομεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 923 na letra τ · nº geral 40381</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 faca de sapateiro 2 fio; gume de faca 3 Medic. fórceps 4 pl. dentes incisivos 5 Geom. setor; segmento (de círculo, de esfera) 6 divisor, ref. a Deus ♦ adj. 7 que corta; cortante (machado) 8 que divide; divisor. 〈τέμνω〉</p></section></article>\n<article id=\"entry-dgp-40382\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τομή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 924 na letra τ · nº geral 40382</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 corte por ablação; decepagem de algo que decepa ou que é decepado, gen.: τ. πελέκεως eur. corte feito por machado, τ. ξύλου sóf. corte de lenha 2 parte decepada do corpo mutilado: ῥιζῶν τομαί sóf. partes cortadas das raízes 3 talho; ferida 4 local do corte; perfuração aberta; corte; fenda; talhe 5 poda (de videira) 6 canal; sulco (da terra) 7 corte e modelagem (do couro) corte; picagem para preparo (de remédio) 8 Anat. incisão ou interseção entre partes de um inseto 9 Medic. incisão cirúrgica 10 Medic. castração 11 Geom. seção; círculo de esfera; seção cônica de um cone 12 Geom. ponto de interseção de duas linhas 13 separação; divisão (de número); distinção (de tempos gramaticais) 14 divisão lógica 15 concisão ou precisão na expressão 16 Métr. cesura. 〈τέμνω〉</p></section></article>\n<article id=\"entry-dgp-40383\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόμιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 925 na letra τ · nº geral 40383</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vítima cortada em pedaços para sacrifício 2 pl. partes da vítima usadas no sacrifício. 〈τομή〉</p></section></article>\n<article id=\"entry-dgp-40384\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τομός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 926 na letra τ · nº geral 40384</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cortante; afiado 2 incisivo; penetrante; preciso. 〈τέμνω〉</p></section></article>\n<article id=\"entry-dgp-40385\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 927 na letra τ · nº geral 40385</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fatia; parte; porção; pedaço 2 Geom. segmento sólido (de cilindro) 3 rolo de papiro 4 tomo; volume 5 documento; carta. 〈τέμνω〉</p></section></article>\n<article id=\"entry-dgp-40386\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόν</h1><div class=\"entry-meta\"><span>DGP · ordem 928 na letra τ · nº geral 40386</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ac. sing. do art. ὁ ou ac. sing. poét. do pron. rel. ὅς 2 = τοῦτον, ac. sing. de οὕτος.</p></section></article>\n<article id=\"entry-dgp-40387\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τονάριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 929 na letra τ · nº geral 40387</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequena flauta afinadora; tonário. 〈τόνος〉</p></section></article>\n<article id=\"entry-dgp-40388\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τονθορίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 930 na letra τ · nº geral 40388</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">τονθορύζω.</p></section></article>\n<article id=\"entry-dgp-40389\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τονθορύζω</h1><div class=\"entry-meta\"><span>DGP · ordem 931 na letra τ · nº geral 40389</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 emitir som inarticulado 2 resmungar; murmurar 3 (porco) grunhir.</p></section></article>\n<article id=\"entry-dgp-40390\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τονικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 932 na letra τ · nº geral 40390</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de ou para esticar; capaz de estender, de tensionar 2 que se estende; que se estira (asa) ♦ τὸ τονικόν 3 Mús. o tom inteiro 4 Gram. acentuação. 〈τόνος〉</p></section></article>\n<article id=\"entry-dgp-40391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 933 na letra τ · nº geral 40391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 corda; tira; faixa 2 tira; correia de cama 3 cordame de jogo de máquina 4 Anat., pl. tendões; nervos 5 ação de esticar, de estender; tensão; tração 6 tensão (de armas): τ. πληγῆς plut. aplicação de um golpe 7 contenção (do espírito) 8 esforço (físico ou mental); força; vigor; energia 9 intensidade 10 tom; volume; altura (de voz) 11 Mús. tom (de instrumento, de escala musical) 12 Métr. ritmo ou metro do verso 13 Gram. acento de palavra ou sílaba. 〈τείνω〉</p></section></article>\n<article id=\"entry-dgp-40392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τονόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 934 na letra τ · nº geral 40392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 esticar; estender 2 dar intensidade, força a, ac. 3 Gram. colocar acento em palavra ou sílaba; acentuar. 〈τόνος〉</p></section></article>\n<article id=\"entry-dgp-40393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τονῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 935 na letra τ · nº geral 40393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = νῦν.</p></section></article>\n<article id=\"entry-dgp-40394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοξάζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 936 na letra τ · nº geral 40394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atirar com o arco contra alguém ou algo, gen. ou ac. 〈τόξον〉</p></section></article>\n<article id=\"entry-dgp-40395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοξάριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 937 na letra τ · nº geral 40395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequeno arco. 〈τόξον〉</p></section></article>\n<article id=\"entry-dgp-40396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόξαρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 938 na letra τ · nº geral 40396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chefe dos arqueiros. 〈τόξον, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-40397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοξάσσαιτο</h1><div class=\"entry-meta\"><span>DGP · ordem 939 na letra τ · nº geral 40397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. opt. aor. ép., τοξάσσεται 3ª sing fut. ép., de τοξάζομαι.</p></section></article>\n<article id=\"entry-dgp-40398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόξευμα, ατος</h1><div class=\"entry-meta\"><span>DGP · ordem 940 na letra τ · nº geral 40398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(τό) 1 tiro de arco; lançamento de flecha, de dardo 2 alcance de um dardo: ἐντὸς τοξεύματος xen. ao alcance de um dardo, ἔξω τοξεύματος tuc. fora do alcance de um dardo 3 dardo; flecha: ὅσον τ. ἐξικνέεται her. quanto dista de um tiro de arco, πρὶν τ. ἐξικνεῖσθαι xen. antes que atinja um tiro de arco 4 flechada (de palavras): καρδίας τοξεύματα sóf. flechada no coração 5 col., pl. tropa de arqueiros. 〈τοξεύω〉</p></section></article>\n<article id=\"entry-dgp-40399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοξευτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 941 na letra τ · nº geral 40399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arqueiro ♦ Τοξευτής 2 Sagitário, constelação. 〈τοξεύω〉</p></section></article>\n<article id=\"entry-dgp-40400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοξευτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 942 na letra τ · nº geral 40400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atingido por uma flecha; flechado. 〈τοξεύω〉</p></section></article>\n";
